/**
 * Example 2: Memory Store & Load (MAR & MDR In Action)
 *
 * Demonstrates:
 *   1. Setting up data in register R1 = 42 (0x002A).
 *   2. Storing R1 into RAM location DATA using ST (Store).
 *      - Effective Address PC + offset generated by gate-level adder -> MAR.
 *      - R1 data routed to MDR.
 *      - MDR written to RAM[MAR].
 *   3. Loading RAM[DATA] into R2 using LD (Load).
 *      - Address -> MAR.
 *      - RAM[MAR] read into MDR.
 *      - MDR written into destination register R2.
 *   4. Verifying R2 equals 42.
 *
 * Run with:
 *   node src/version3/src/examples/run-memory.js
 */

import { Assembler } from '../assembler/assembler.js';
import { CPU } from '../cpu/cpu.js';

const source = `
.ORIG 0x3000
AND R1, R1, #0
ADD R1, R1, #15
ADD R1, R1, #15
ADD R1, R1, #12    ; R1 = 42 (15 + 15 + 12)
ST  R1, DATA       ; Store 42 into memory variable DATA
AND R2, R2, #0     ; Clear R2 = 0
LD  R2, DATA       ; Load from memory variable DATA into R2
HALT

DATA:
.FILL 0x0000       ; Reserved storage slot
.END
`;

console.log('='.repeat(75));
console.log('  EXAMPLE 2: MEMORY INTERFACE (MAR & MDR) READ / WRITE VERIFICATION');
console.log('='.repeat(75));

const assembler = new Assembler();
const binary = assembler.assemble(source);

console.log('Assembly Listing:');
for (const stmt of binary.machineCode) {
  console.log(`  [0x${stmt.address.toString(16).toUpperCase()}] ${stmt.hex}  |  ${stmt.raw}`);
}
console.log(`Symbols:`, binary.symbols);
console.log('');

const cpu = new CPU(binary.origin);
cpu.ram.loadProgram(binary.origin, binary.words);

let instCount = 0;
while (cpu.controlUnit.currentState !== 'HALTED') {
  instCount++;
  console.log(`--- [ Instruction #${instCount} ] ---`);
  do {
    const cycle = cpu.clock.cycleCount + 1;
    const stateBefore = cpu.controlUnit.currentState;
    cpu.stepClock();
    const trace = cpu.lastTrace;
    console.log(`  Cycle ${String(cycle).padStart(2)}: State=${stateBefore.padEnd(10)} -> ${trace.notes}`);
  } while (cpu.controlUnit.currentState !== 'FETCH_1' && cpu.controlUnit.currentState !== 'HALTED');

  console.log(`  => Current: R1=${cpu.regFile.getReg(1)}, R2=${cpu.regFile.getReg(2)}\n`);
}

const dataAddress = binary.symbols['DATA'];
const storedValueInRAM = cpu.ram.read(dataAddress);

console.log('='.repeat(75));
console.log('FINAL MEMORY AUDIT:');
console.log(`RAM at DATA (0x${dataAddress.toString(16).toUpperCase()}): ${storedValueInRAM} (Expected: 42)`);
console.log(`R2 loaded from RAM:       ${cpu.regFile.getReg(2)} (Expected: 42)`);
console.log(`Total Cycles:             ${cpu.clock.cycleCount}`);
console.log(`CPU Halted:               ${cpu.controlUnit.currentState === 'HALTED' ? 'YES' : 'NO'}`);

if (cpu.regFile.getReg(2) === 42 && storedValueInRAM === 42) {
  console.log('\n[SUCCESS] Memory Read/Write through MAR and MDR completed successfully!');
} else {
  console.error('\n[FAILURE] Memory load/store mismatch!');
  process.exit(1);
}
console.log('='.repeat(75));

